//! Randomly generated expression trees — do not edit by hand.
//!
//! Regenerate with:
//!
//! ```text
//! scripts/gen-fuzz-corpus.py --seed 1 --count 200 --nodes 40 \
//!     > reassoc/tests/fuzz_corpus.rs
//! ```
//!
//! Each case asserts three things about the same tree:
//!
//! 1. `alg!(tree)` equals the value computed exactly, offline, in rational
//!    arithmetic — so both the rewriter and the plain form would have to be
//!    wrong in the same way to pass.
//! 2. `alg!(tree)` equals the plain form bit for bit. The generator only emits
//!    dyadic rationals inside f64's exact range, so reassociation and
//!    contraction cannot legitimately change the result; any difference is a
//!    bug in the rewrite.
//! 3. The same tree inside `#[algebraic]` agrees too, so the attribute and the
//!    expression macro cannot drift apart.
//!
//! Seed 1, 200 trees of ~40 nodes.
#![allow(clippy::float_cmp, clippy::eq_op, clippy::neg_multiply)]
#![allow(unused_parens)]

use reassoc::{alg, algebraic};

const A: f64 = 3.0;
const B: f64 = -2.0;
const C: f64 = 5.0;
const D: f64 = 0.5;
const E: f64 = -7.0;
const F: f64 = 0.25;
const G: f64 = 11.0;
const H: f64 = -0.125;

#[algebraic]
fn attr_0() -> [f64; 20] {
    let (a, b, c, d, e, f, g, h) = (A, B, C, D, E, F, G, H);
    [
        ((h * (1.0 / 4.0))
            % (((a * 4.0) - ((((((3.0 - 4.0) - b) / 2.0) - -2.0) + -1.0) / 4.0)) / 2.0)),
        (((-(((((3.0 % -1.0) % ((-(3.0 * a)) + a)) + (h % d)) % ((h % d) / 4.0)) + g))
            - ((-((-1.0 * 4.0) / 2.0)) * (c * ((-(e - d)) - ((g % a) + e)))))
            - (((a * 4.0) + (c + c)) / 2.0)),
        (((((3.0 / 8.0) * (d + e))
            - (((e % a) + (((a % (-2.0 % (1.0 + 2.0))) * (2.0 + 4.0)) / 8.0)) / 2.0))
            * (a - d))
            - (e * (4.0 * 2.0))),
        (((a + ((e - f) % (h * g))) - (((((4.0 % g) + 3.0) - d) / 8.0) + (c * g)))
            % (e % (((((-(e - g)) * (c + g)) - d) % ((f + (e / 4.0)) * ((-2.0 - a) * 4.0)))
                / 2.0))),
        ((((4.0 - g) / 2.0) % (((c * (h + c)) * g) / 4.0))
            % ((3.0 + -1.0)
                + ((-((c
                    - (e % ((1.0 / 2.0) - ((c + (g * (-(-2.0 * d)))) + ((-1.0 % d) * b)))))
                    - (-(d + 1.0))))
                    - (((h / 4.0) / 8.0) % -2.0)))),
        ((c - 2.0)
            - (((b * (2.0 % c)) + h)
                % (((-((d / 2.0) / 4.0)) - (e * (-1.0 % e)))
                    * (((-(((-((c % a) - -1.0)) / 4.0)
                        % (-(((c / 2.0) * (e * 4.0)) * (h / 4.0)))))
                        % (-(1.0 - (b * c))))
                        % (((-(1.0 * ((c + a) % b))) - h) + ((d + e) + -1.0)))))),
        (((-((b + e) * c)) + a) / 4.0),
        (((((a + a) / 4.0) - (h * h))
            * ((f + f)
                + ((((-2.0 - f) % (f + f))
                    - ((b - ((-2.0 % a) % (((f - h) - (d * g)) - (g * a))))
                        % ((1.0 - (d * g)) % ((d - c) - (g % a)))))
                    - d)))
            * b),
        ((1.0 % (g * c)) / 2.0),
        (((b * 4.0)
            % (3.0
                % (((g - ((b * 2.0) * (b * c))) - (e - b))
                    * ((f - ((f - (-(4.0 + -1.0))) * g))
                        % ((-1.0 % e) - (((-(a % h)) / 2.0) + ((e + f) + (d + (-1.0 % h)))))))))
            * (d * (-((h % c) % (g % e))))),
        ((((-(((f / 4.0) - 3.0) / 2.0)) - (g - h)) % (((d + (c / 8.0)) - -2.0) - (a / 4.0)))
            * ((e / 2.0)
                * ((((a + f) + d) + e)
                    + ((-(h / 2.0)) - ((-(2.0 - (3.0 - (((b - a) + d) + -1.0)))) * (f * g)))))),
        ((((-((-((f * g) % f)) / 4.0)) + f)
            + (-((h * (-2.0 % -2.0)) + ((c + ((d + d) + a)) - (3.0 % (((e + b) - b) / 4.0))))))
            % (g * (-(h * (-(2.0 - d)))))),
        (((h / 8.0) - (-(d % 2.0))) * a),
        ((((((c / 8.0) - d) - ((-(3.0 / 4.0)) % (c / 4.0))) % ((-(c - 2.0)) % c)) * (a % c))
            * (((c + (3.0 - 3.0)) + h) % (a - (d * (-(1.0 + 3.0)))))),
        (((((-((-(d - (g - h))) * -1.0)) / 8.0) * (((b + c) + c) * a)) * ((b + g) % g))
            - (((-(f + (d + (-(g + 2.0))))) * (((h + e) * 4.0) / 8.0)) / 8.0)),
        ((-((((-(e / 8.0)) % (f / 8.0))
            - ((((a / 4.0) / 2.0) % (h - (c * (a % e)))) + (-(g - a))))
            + (((h * (f % -1.0)) - g) * g)))
            - (g - (-((g % b) + ((4.0 + (-(b * g))) - (d - g)))))),
        (-((-(((f + h) + ((d * (e - 3.0)) * ((2.0 - (c + b)) / 8.0)))
            + ((-((e + 3.0) + ((-(-2.0 + 4.0)) * h))) / 2.0)))
            * (1.0 - e))),
        (((((h * ((a - 2.0) % g)) % 1.0) / 4.0) % (3.0 * c))
            * (-((b / 8.0) - ((-((-2.0 / 2.0) - f)) / 8.0)))),
        ((d + ((a - (c - g)) / 2.0)) - ((c % b) / 4.0)),
        ((-((((g + 3.0) / 2.0) / 4.0) + ((d / 8.0) % (4.0 + g)))) / 8.0),
    ]
}

